from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult

def extract_invoice_fields(payload, config=None):
    config = config or {}
    endpoint = os.environ["DOCUMENTINTELLIGENCE_ENDPOINT"]
    key = os.environ["DOCUMENTINTELLIGENCE_API_KEY"]

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    poller = document_intelligence_client.begin_analyze_document(
        "prebuilt-invoice", analyze_request=payload, content_type="application/octet-stream"
    )
    analysis: AnalyzeResult = poller.result()

    extracted_data = {}

    if analysis.documents:
        invoice = analysis.documents[0]

        vendor = invoice.fields.get("VendorName")
        if vendor and vendor.content:
            extracted_data["vendor"] = vendor.content

        invoice_date = invoice.fields.get("InvoiceDate")
        if invoice_date and invoice_date.value:
            extracted_data["date"] = str(invoice_date.value)

        total = invoice.fields.get("InvoiceTotal")
        if total and total.value:
            extracted_data["total"] = total.value.amount

        line_items = []
        items_field = invoice.fields.get("Items")
        if items_field and items_field.value:
            for item_field in items_field.value:
                item = item_field.value
                line_item = {}
                description = item.get("Description")
                if description and description.content:
                    line_item["description"] = description.content

                quantity = item.get("Quantity")
                if quantity and quantity.value is not None:
                    line_item["quantity"] = quantity.value

                unit_price = item.get("UnitPrice")
                if unit_price and unit_price.value:
                    line_item["unit_price"] = unit_price.value.amount

                amount = item.get("Amount")
                if amount and amount.value:
                    line_item["amount"] = amount.value.amount

                if line_item:
                    line_items.append(line_item)

        if line_items:
            extracted_data["line_items"] = line_items

    result = extracted_data
    return result
